function matchAccountBrand(name) {
  const n = String(name || "").toLowerCase();
  let best = null;
  ACCOUNT_BRANDS.forEach(b => {
    (b.aliases || []).forEach(a => {
      const alias = String(a || "").toLowerCase();
      if (alias && n.indexOf(alias) >= 0 && (!best || alias.length > best.len)) best = { id: b.id, len: alias.length };
    });
  });
  return best ? best.id : null;
}
